function m8MonoCoef() { var a = rand(2, 12), m = rand(1, 3); return numMCQ6("Hệ số của đơn thức sau là bao nhiêu?", mono8(a, m, rand(0, 2)), a, "Hệ số là phần số của đơn thức: " + a + ".", 4); }
