  if (Math.random() < 0.5) return numMCQ6("Tính tổng hai đa thức rồi cho biết hệ số của x²!", "(" + a + "x² + " + b + "x) + (" + c + "x² − " + d + "x)", a + c, "Cộng các đơn thức đồng dạng: hệ số của x² là " + a + " + " + c + " = " + (a + c) + ".", 5);
  return numMCQ6("Tính tổng hai đa thức rồi cho biết hệ số của x!", "(" + a + "x² + " + b + "x) + (" + c + "x² − " + d + "x)", b - d, "Hệ số của x là " + b + " − " + d + " = " + (b - d) + ".", 4);
