  if (Math.random() < 0.5) return numMCQ6("Nhân hai đơn thức: hệ số của tích là bao nhiêu?", "(" + a + "x" + sup8(m) + ") · (" + b + "x" + sup8(n) + ")", a * b, "Nhân hệ số với hệ số: " + a + " × " + b + " = " + (a * b) + "; nhân phần biến: x" + sup8(m) + " · x" + sup8(n) + " = x" + sup8(m + n) + ".", 6);
  return numMCQ6("Nhân hai đơn thức: số mũ của x trong tích là bao nhiêu?", "(" + a + "x" + sup8(m) + ") · (" + b + "x" + sup8(n) + ")", m + n, "Khi nhân hai luỹ thừa cùng cơ số, ta cộng các số mũ: " + m + " + " + n + " = " + (m + n) + ".", 3);
