function m8SqPlus() { var a = rand(2, 9); var ans = "x² + " + (2 * a) + "x + " + (a * a); return mcqQ("Khai triển (x + " + a + ")² được kết quả nào?", ["x² + " + a + "x + " + (a * a), "x² + " + (2 * a) + "x + " + (2 * a), "x² − " + (2 * a) + "x + " + (a * a)], ans, "(a + b)² = a² + 2ab + b² nên (x + " + a + ")² = x² + " + (2 * a) + "x + " + (a * a) + "."); }
