function climateSVG8() {
  var months = ["1", "4", "7", "10"], rain = [18, 90, 290, 260], temp = [17, 24, 29, 26];
  var out = '<svg width="260" height="170" viewBox="0 0 260 170" role="img">';
  rain.forEach(function (v, i) { var h = Math.round(v / 300 * 95); var x = 25 + i * 58; out += '<rect x="' + x + '" y="' + (125 - h) + '" width="34" height="' + h + '" fill="#4a90c2" stroke="#2f6f9f" stroke-width="2"/><text x="' + (x + 17) + '" y="' + (118 - h) + '" font-size="13" font-weight="bold" text-anchor="middle" fill="#333">' + v + '</text><text x="' + (x + 17) + '" y="148" font-size="12" text-anchor="middle" fill="#333">Th' + months[i] + "</text>"; });
  var pts = temp.map(function (t, i) { return (42 + i * 58) + "," + (125 - Math.round(t / 40 * 95)); }).join(" ");
  out += '<polyline points="' + pts + '" fill="none" stroke="#d9534f" stroke-width="3"/>';
  temp.forEach(function (t, i) { out += '<circle cx="' + (42 + i * 58) + '" cy="' + (125 - Math.round(t / 40 * 95)) + '" r="4" fill="#d9534f"/><text x="' + (42 + i * 58) + '" y="' + (112 - Math.round(t / 40 * 95)) + '" font-size="12" font-weight="bold" text-anchor="middle" fill="#d9534f">' + t + "°</text>"; });
  return out + "</svg>";
}
