function tin8Formula() {
  var v = rand(0, 3);
  if (v === 0) { var a = rand(3, 20), b = rand(3, 20), c = rand(3, 20); return numMCQ6("Trong bảng tính, ô D1 chứa công thức =A1+B1+C1 với A1 = " + a + ", B1 = " + b + ", C1 = " + c + ". Kết quả ở D1 là bao nhiêu?", "=A1+B1+C1", a + b + c, "Tính lần lượt: " + a + " + " + b + " + " + c + " = " + (a + b + c) + ".", 8); }
  if (v === 1) { var a2 = rand(4, 30), b2 = rand(2, a2 - 1); return numMCQ6("Ô C2 chứa công thức =SUM(A2:B2) với A2 = " + a2 + ", B2 = " + b2 + ". Kết quả là bao nhiêu?", "=SUM(A2:B2)", a2 + b2, "SUM cộng tổng các ô trong vùng: " + a2 + " + " + b2 + " = " + (a2 + b2) + ".", 7); }
  if (v === 2) { var n = pick([10, 20, 30, 40]), k = pick([2, 4, 5]); var tot = n * k; return numMCQ6("Vùng A1:A" + k + " có các số đều bằng " + n + ". Hàm =AVERAGE(A1:A" + k + ") cho kết quả bao nhiêu?", "=AVERAGE(...)", n, "Trung bình cộng của " + k + " số bằng nhau (đều " + n + ") vẫn là " + n + ".", 5); }
  var m = rand(15, 60), m2 = rand(61, 99); return numMCQ6("Vùng B1:B3 chứa các số " + m + ", " + m2 + ", " + rand(20, 50) + ". Hàm =MAX(B1:B3) cho kết quả bao nhiêu?", "=MAX(B1:B3)", m2, "MAX trả về giá trị lớn nhất trong vùng: " + m2 + ".", 12);
}
function tin8Output() {
  var v = rand(0, 2);
  if (v === 0) { var n = pick([4, 5, 6]); return numMCQ6("Cho đoạn chương trình: s ← 0; với i chạy từ 1 đến " + n + ": s ← s + i. Kết thúc, s bằng bao nhiêu?", "s = ?", n * (n + 1) / 2, "s = 1 + 2 + ... + " + n + " = " + (n * (n + 1) / 2) + ".", 4); }
  if (v === 1) { var a = rand(3, 15); return mcqQ("Cho đoạn chương trình: nhập a = " + a + "; nếu a chia hết cho 2 thì in “Chẵn”, ngược lại in “Lẻ”. Chương trình in ra gì?", ["Lẻ", "Không in gì", "In cả hai dòng"], a % 2 === 0 ? "Chẵn" : "Lẻ", a + (a % 2 === 0 ? " là số chẵn nên in “Chẵn”." : " là số lẻ nên in “Lẻ”.")); }
  var x = rand(2, 9); return numMCQ6("Cho đoạn chương trình: x ← " + x + "; x ← x × 3; x ← x − " + x + ". Kết thúc, x bằng bao nhiêu?", "x = ?", x * 3 - x, "x = " + x + " × 3 = " + (x * 3) + "; sau đó x = " + (x * 3) + " − " + x + " = " + (x * 3 - x) + ".", 5);
}
